CHAINS=[{'chain': '600136-担保终局有利，经营是否跟上', 'source': '1225420862', 'pages': [1, 2], 'subject': '担保终局有利，经营是否跟上', 'changed': '7月终局仲裁确认差额补足承诺函对公司不生效，不承担该案责任，公司称此前7项违规担保已解除。', 'open': '公司自担仲裁费387336元不当回款；处罚时间条件及正式撤销另核。前三季归母、扣非和经营现金均负，不能把担保解除当经营恢复。', 'supporting': []}, {'chain': '600136-另一组诉讼终审，不与担保案混接', 'source': '1225663116', 'pages': [1, 2], 'subject': '另一组诉讼终审，不与担保案混接', 'changed': '11月披露鄂民终219、220号维持原判，驳回北京福升上诉；涉及金额119460448.21元含暂计利息。', 'open': '这是虚假陈述赔偿上诉，不是05214担保仲裁；不把无需承担赔偿写成等额现金流入。', 'supporting': []}, {'chain': '600136-买房是资金用途，合同不等于付款', 'source': '1225557731', 'pages': [1, 2], 'subject': '买房是资金用途，合同不等于付款', 'changed': '控股子公司拟以508.80万元购买关联方8项商业房地产，董事会已审议。', 'open': '约定2026年12月31日前一次付清；本件未证明已支付及交割，不能当卖房回款或重大资产重组。', 'supporting': []}, {'chain': '600165-摘帽落地，亏损和新诉讼仍需看', 'source': '1225497764', 'pages': [1, 2, 3], 'subject': '摘帽落地，亏损和新诉讼仍需看', 'changed': '8月15日申请，8月24日获准，25日停牌，26日撤销其他风险警示并转出风险警示板。', 'open': '摘帽不是经营风险消失。三季度归母亏5853.26万元、扣非亏6004.98万元、经营现金流出7450.83万元。申请和批准分段比较，不把涨幅归因摘帽净效应。', 'supporting': [{'source': '1225475518', 'pages': [1]}, {'source': '1225650652', 'pages': [1]}]}, {'chain': '600165-技术秘密诉讼不同于旧专利强调事项', 'source': '1225425493', 'pages': [1, 2, 3], 'subject': '技术秘密诉讼不同于旧专利强调事项', 'changed': '7月披露（2026）京民初5号立案，尚未开庭，诉求涉及核心月桂二酸技术；公司为被告九、子公司为被告十。', 'open': '原告诉请不是公司确认债务或已判侵权。首页96586.25万元与正文96587.25万元不一致，另有100万元合理费用，保留冲突、不选一数精算总敞口。公司否认侵权属当事人立场。', 'supporting': []}, {'chain': '600165-追偿权终审胜诉，不能覆盖技术秘密案', 'source': '1225487892', 'pages': [1, 2], 'subject': '追偿权终审胜诉，不能覆盖技术秘密案', 'changed': '8月另一追偿权纠纷终审驳回上诉、维持原判，公司不承担连带责任。', 'open': '7904611.11元及费用对应华辉环保追偿案，不代表北京技术秘密案或此前南京专利案结案。', 'supporting': []}, {'chain': '600169-扣非转正和现金改善，仍分开看处罚', 'source': '1225648979', 'pages': [2, 4], 'subject': '扣非转正和现金改善，仍分开看处罚', 'changed': '三季度归母5894.31万元、扣非3093.39万元，前三季扣非2702.39万元，较半年扣非负391.01万元改善；前三季经营现金26.03亿元。', 'open': '季度现金14.47亿元由累计减半年推算，非原表直接季度披露；同控合并采用调整后同比。经营改善不等于处罚警示正式解除，原件作出日和正式撤销继续核。', 'supporting': [{'source': '1225498049', 'pages': [5, 6]}]}, {'chain': '600180-签投资人后，哪些钱和程序还没到', 'source': '1225564124', 'pages': [1, 2, 6, 7, 8], 'subject': '签投资人后，哪些钱和程序还没到', 'changed': '9月确定金正实业并签重整投资协议，拟6亿元认购6亿股；初步确认债权75.09亿元、暂缓确认125.40亿元分别列示。', 'open': '1000万元报名保证金以投标保证保险保单方式，不当现金到账；6000万元履约保证金可用保函等形式，6亿元投资款有法院批准方案后通知等条件。签约仍非司法受理、方案批准或全款收到。', 'supporting': []}, {'chain': '600180-现金短期转正，不足以证明业务恢复', 'source': '1225649881', 'pages': [1, 2, 3, 4], 'subject': '现金短期转正，不足以证明业务恢复', 'changed': '前三季收入8.91亿元，三季度仅0.87亿元；三季度归母亏13.88亿元、扣非亏13.74亿元；季度经营现金约3678.85万元为正，累计仍流出4270.80万元。', 'open': '季度现金用累计减半年得到。收入收缩、减值和联营收益变化要与回款并看；不把单季现金为正或协议签订当危机解除。', 'supporting': [{'source': '1225527619', 'pages': [5, 10]}]}, {'chain': '600180-低于1元要逐日计数，不能拼接两段', 'source': '1225668568', 'pages': [1, 2], 'subject': '低于1元要逐日计数，不能拼接两段', 'changed': '未复权收盘价两源核对：11月2、3日低于1元，4日回升打断，9日恰为1元；12日至19日连续6个交易日低于1元。', 'open': '同份公告首次日期措辞冲突保留；只计算已核窗口，不认定全历史首次、不把6日说成20日，不推测19日之后。', 'supporting': []}]
