def followup_view(inputs, prior):
    packet=inputs.get('fourteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('fourteenth period packet changed')
    if prior is None or prior['counts']['after']!=98 or packet['prior_digest']!=digest(prior):raise ValueError('fourteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('fourteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=26 or len(packet['sources'])!=26 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('fourteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('fourteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('fourteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('fourteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('fourteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('fourteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('fourteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('fourteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('fourteenth period quarter changed')
        if row['reported_quarter_yuan']is not None and D(row['reported_quarter_yuan'])!=nine-h:raise ValueError('fourteenth period reported quarter changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('fourteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('fourteenth period windows changed')
    if packet['low_price_digest']!=digest(LOW_PRICE) or packet['financial_conflict_digest']!=digest(FINANCIAL_CONFLICT):raise ValueError('fourteenth period uncertainty changed')
    return {'through':'2026-11-19','title':'摘帽、经营改善和重组签约，各自证明了什么？','answer':'宁科已正式摘帽，三季度仍亏损和现金净流出；太重扣非转正、经营现金改善，处罚警示另核。明诚担保和另一诉讼终审有利，经营仍弱；瑞茂已签投资人但尚非司法重整，保证保险不当现金到账，单季现金转正仍伴随收入萎缩与亏损扩大。','chains':CHAINS,'financial_bridge':FINANCIAL,'event_windows':windows,'financial_source_conflict':FINANCIAL_CONFLICT,'low_price_review':LOW_PRICE,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':26,'new_files':26,'reused_files':0,'pages':972,'new_pages':972,'viewed_pages':len(VISUAL),'initial_coverage':98,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'26份972页仅15关键页视觉核对，不称全文已阅。78窗口69满9未满，宁科停牌日保留空值，88股价端点跨渠道核验沿用1e-9浮点门槛；不关闭别批历史报价差异。16半年10项与披露同比一致、6仅另算；16季度13直接披露3现金差额推算。太重同比用同控调整后比较数；宁科半年报上年末数据内部冲突不自行纠正，京民初5号诉请首页与正文金额冲突保留。瑞茂两段低价不拼接，保险保单不当现金，签约不当法院受理。公告窗口是描述性同窗，不识别净因果，不把重复公告晋级通用经验。','method_promotions':0}
